choreos:
protocol W {
  roles A, J, C;
  A -> J : First(x: Int) verified;
  J -> C : Weak() oracle;
}

protocol M {
  roles A, J;
  A -> J : Draft(x: Int) [x <= 100] oracle;
}

protocol G {
  roles A, J, C;
  A -> J : Pre(x: Int) verified;
  choice approval at J -> C {
    Go consent: { J -> A : Ok(); }
    Stop: { J -> A : No(); }
  }
}

protocol X {
  roles A, J, C;
  A -> J : First(x: Int) verified;
  J -> C : Mid() oracle;
  C -> A : Last(y: Int) verified;
}

protocol P {
  roles A, J;
  A -> J : Msg();
}
